package com.focusflow.api.controller; import com.focusflow.api.dto.ApiDtos.*; import com.focusflow.api.service.CategoryService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/categories") public class CategoryController {final CategoryService service;public CategoryController(CategoryService s){service=s;}String uid(Authentication a){return(String)a.getPrincipal();}@GetMapping List<CategoryResponse> all(Authentication a){return service.all(uid(a));}@PostMapping @ResponseStatus(HttpStatus.CREATED) CategoryResponse create(@Valid @RequestBody CategoryRequest r,Authentication a){return service.create(r,uid(a));}@PutMapping("/{id}") CategoryResponse update(@PathVariable String id,@Valid @RequestBody CategoryRequest r,Authentication a){return service.update(id,r,uid(a));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable String id,Authentication a){service.delete(id,uid(a));} }
